        'labels': {             # labelname -> docname, labelid, sectionname
            'genindex': ('genindex', '', _('Index')),
            'modindex': ('py-modindex', '', _('Module Index')),
            'search': ('search', '', _('Search Page')),
        },
        'anonlabels': {         # labelname -> docname, labelid
            'genindex': ('genindex', ''),
            'modindex': ('py-modindex', ''),
            'search': ('search', ''),
        },
    }

    dangling_warnings = {
        'term': _('term not in glossary: %(target)s'),
        'token': _('grammar token not in grammar: %(target)s'),
        'ref': _('undefined label: %(target)s'),
        'numref': _('undefined label: %(target)s'),
        'option': _('unknown option: %(target)s'),
        'envvar': _('unknown environment variable: %(target)s'),
    }

    # node_class -> (figtype, title_getter)
    enumerable_nodes = {
        nodes.figure: ('figure', None),
        nodes.table: ('table', None),
        nodes.container: ('code-block', None),
    }

    def __init__(self, env: "BuildEnvironment") -> None:
        super().__init__(env)

        # set up enumerable nodes
        self.enumerable_nodes = copy(self.enumerable_nodes)  # create a copy
        for node, (figtype, title_getter) in self.enumerable_nodes.items():
            self.enumerable_nodes[node] = (figtype, title_getter)

    def clear_doc(self, docname: str) -> None:
        for key, (fn, _labelid) in list(self.data['labels'].items()):
            if fn == docname:
                del self.data['labels'][key]
        for key, (fn, _labelid) in list(self.data['anonlabels'].items()):
            if fn == docname:
                del self.data['anonlabels'][key]

        for (prog, option) in list(self.data['progoptions'].keys()):
            if self.data['progoptions'][(prog, option)][0] == docname:
                del self.data['progoptions'][(prog, option)]

        for (type, name) in list(self.data['objects'].keys()):
            if self.data['objects'][(type, name)][0] == docname:
                del self.data['objects'][(type, name)]

    def merge_domaindata(self, docnames: List[str], otherdata: Dict) -> None:
        # XXX check duplicates
        for key, data in otherdata['progoptions'].items():
            if data[0] in docnames:
                self.data['progoptions'][key] = data
        for key, data in otherdata['objects'].items():
            if data[0] in docnames:
                self.data['objects'][key] = data
        for key, data in otherdata['labels'].items():
            if data[0] in docnames:
                self.data['labels'][key] = data
        for key, data in otherdata['anonlabels'].items():
            if data[0] in docnames:
                self.data['anonlabels'][key] = data

    def process_doc(self, env: "BuildEnvironment", docname: str,
                    document: nodes.document) -> None:
        # note_object
        for node in document.traverse(addnodes.desc):
            if node.get('domain') != 'std':
                continue
            for desc_signature in node.traverse(desc_signature):
                if desc_signature.get('ids'):
                    self.note_object(desc_signature.get('objtype'),
                                     desc_signature.get('fullname'),
                                     desc_signature['ids'][0],
                                     location=desc_signature)

        # note labels
        for name, explicit in document.nametypes.items():
            if not explicit:
                continue
            labelid = document.nameids[name]
            if labelid is None:
                continue
            node = document.ids[labelid]
            if name.isdigit():
                # may be for a footnote whose label is not known
                continue
            if name == 'genindex' or name == 'modindex' or name == 'search':
                continue
            if name in self.data['labels']:
                logger.warning(__('duplicate label %s, other instance in %s'),
                               name, self.env.doc2path(self.data['labels'][name][0]),
                               location=node)
            self.data['anonlabels'][name] = (docname, labelid)
            if isinstance(node, (nodes.section, nodes.transition)):
                title = cast(nodes.title, node[0]).astext()
            elif isinstance(node, nodes.title):
                title = node.astext()
            elif isinstance(node, nodes.table):
                title = ''
                for t in node.traverse(nodes.title):
                    title += t.astext()
            else:
                title = node.astext()
            self.data['labels'][name] = (docname, labelid, title)

        # note options
        for progname, options in env.ref_context.get('std:program', {}).items():
            for option in options:
                self.data['progoptions'][(progname, option)] = (docname, '')

    def note_object(self, objtype: str, name: str, labelid: str,
                    location: Node = None) -> None:
        """Note a generic object for cross reference.

        .. versionadded:: 2.1
        """
        if (objtype, name) in self.data['objects']:
            docname = self.data['objects'][(objtype, name)][0]
            logger.warning(__('duplicate object description of %s, '
                              'other instance in %s'), name, docname,
                           location=location)
        self.data['objects'][(objtype, name)] = (self.env.docname, labelid)

    def note_label(self, name: str, location: Node = None) -> None:
        """Note a label for cross reference.

        .. versionadded:: 2.1
        """
        if name in self.data['labels']:
            docname = self.data['labels'][name][0]
            logger.warning(__('duplicate label %s, other instance in %s'),
                           name, docname, location=location)
        self.data['anonlabels'][name] = (self.env.docname, '')

    def add_program_option(self, program: str, name: str, docname: str,
                           labelid: str) -> None:
        self.data['progoptions'][(program, name)] = (docname, labelid)

